+func runSemanticSnapshot(ctx context.Context, runner CommandRunner, repoDir, semBinary string, worktree bool) ([]byte, error) {
+	args := []string{"sem", "snapshot", "--repo", repoDir, "--format", "ndjson", "--no-network"}
+	if worktree {
