  1902	FROM symbols s
  1903	JOIN symbol_fts f ON f.id = s.id
  1904	WHERE instr(lower(f.text), ?) > 0
  1905	ORDER BY CASE WHEN lower(s.name) = lower(?) THEN 0 WHEN lower(s.qualified_name) = lower(?) THEN 1 ELSE 2 END, s.qualified_name
  1906	LIMIT ? OFFSET ?`, literal, query, query, limit, offset)
  1907		if err != nil {
  1908			return nil, err
  1909		}
