  2827	func resolvedOutputPath(output string) (string, error) {
  2828		if resolved, err := filepath.EvalSymlinks(output); err == nil {
  2829			return filepath.Abs(resolved)
  2830		}
  2831		absOutput, err := filepath.Abs(output)
  2832		if err != nil {
  2833			return "", err
  2834		}
  2835		volume := filepath.VolumeName(absOutput)
  2836		rest := strings.TrimPrefix(absOutput, volume)
  2837		parts := strings.Split(strings.Trim(rest, string(filepath.Separator)), string(filepath.Separator))
  2838		existing := volume + string(filepath.Separator)
  2839		var missing []string
  2840		for i, part := range parts {
  2841			candidate := filepath.Join(existing, part)
  2842			if _, err := os.Lstat(candidate); err != nil {
  2843				if os.IsNotExist(err) {
  2844					missing = parts[i:]
  2845					break
  2846				}
  2847				return "", err
  2848			}
  2849			existing = candidate
  2850		}
  2851		resolvedExisting, err := filepath.EvalSymlinks(existing)
  2852		if err != nil {
  2853			return "", err
  2854		}
  2855		for _, part := range missing {
  2856			resolvedExisting = filepath.Join(resolvedExisting, part)
  2857		}
  2858		return filepath.Abs(resolvedExisting)
  2859	}
